-- CrimeMind canonical Oracle 11g schema. Run as CRIMEMIND.
CREATE TABLE entity_types(entity_type_id NUMBER(5) PRIMARY KEY,type_name VARCHAR2(50) NOT NULL UNIQUE);
CREATE TABLE entities(entity_id NUMBER(19) PRIMARY KEY,entity_type_id NUMBER(5) NOT NULL,display_name VARCHAR2(200) NOT NULL,external_reference VARCHAR2(100) UNIQUE,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,CONSTRAINT fk_entities_type FOREIGN KEY(entity_type_id) REFERENCES entity_types(entity_type_id));
CREATE TABLE locations(location_id NUMBER(19) PRIMARY KEY,external_reference VARCHAR2(100) UNIQUE,location_name VARCHAR2(200) NOT NULL,location_type VARCHAR2(100),address VARCHAR2(500),latitude NUMBER(10,7),longitude NUMBER(10,7),geom MDSYS.SDO_GEOMETRY,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,CONSTRAINT ck_loc_lat CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90),CONSTRAINT ck_loc_lon CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180));
CREATE TABLE event_types(event_type_id NUMBER(5) PRIMARY KEY,type_name VARCHAR2(50) NOT NULL UNIQUE);
CREATE TABLE events(event_id NUMBER(19) PRIMARY KEY,event_type_id NUMBER(5) NOT NULL,event_time TIMESTAMP WITH TIME ZONE NOT NULL,end_time TIMESTAMP WITH TIME ZONE,location_id NUMBER(19),source_reference VARCHAR2(500),confidence_score NUMBER(5,4),description CLOB,attributes CLOB DEFAULT '{}' NOT NULL,CONSTRAINT fk_events_type FOREIGN KEY(event_type_id) REFERENCES event_types(event_type_id),CONSTRAINT fk_events_location FOREIGN KEY(location_id) REFERENCES locations(location_id),CONSTRAINT ck_events_conf CHECK(confidence_score IS NULL OR confidence_score BETWEEN 0 AND 1),CONSTRAINT ck_events_time CHECK(end_time IS NULL OR end_time>=event_time));
CREATE TABLE entity_events(entity_event_id NUMBER(19) PRIMARY KEY,entity_id NUMBER(19) NOT NULL,event_id NUMBER(19) NOT NULL,role VARCHAR2(100),CONSTRAINT fk_ee_entity FOREIGN KEY(entity_id) REFERENCES entities(entity_id) ON DELETE CASCADE,CONSTRAINT fk_ee_event FOREIGN KEY(event_id) REFERENCES events(event_id) ON DELETE CASCADE,CONSTRAINT uq_ee_event UNIQUE(entity_id,event_id,role));
CREATE TABLE relationship_types(relationship_type_id NUMBER(5) PRIMARY KEY,type_name VARCHAR2(50) NOT NULL UNIQUE,is_directional NUMBER(1) DEFAULT 0 NOT NULL,CONSTRAINT ck_rel_dir CHECK(is_directional IN(0,1)));
CREATE TABLE entity_relationships(relationship_id NUMBER(19) PRIMARY KEY,relationship_type_id NUMBER(5) NOT NULL,source_entity_id NUMBER(19) NOT NULL,target_entity_id NUMBER(19) NOT NULL,strength_score NUMBER(5,4),valid_from TIMESTAMP WITH TIME ZONE,valid_to TIMESTAMP WITH TIME ZONE,attributes CLOB DEFAULT '{}' NOT NULL,CONSTRAINT fk_rel_type FOREIGN KEY(relationship_type_id) REFERENCES relationship_types(relationship_type_id),CONSTRAINT fk_rel_source FOREIGN KEY(source_entity_id) REFERENCES entities(entity_id) ON DELETE CASCADE,CONSTRAINT fk_rel_target FOREIGN KEY(target_entity_id) REFERENCES entities(entity_id) ON DELETE CASCADE,CONSTRAINT ck_rel_strength CHECK(strength_score IS NULL OR strength_score BETWEEN 0 AND 1),CONSTRAINT ck_rel_self CHECK(source_entity_id<>target_entity_id),CONSTRAINT ck_rel_dates CHECK(valid_to IS NULL OR valid_from IS NULL OR valid_to>=valid_from));
CREATE TABLE communication_types(communication_type_id NUMBER(5) PRIMARY KEY,type_name VARCHAR2(50) NOT NULL UNIQUE);
CREATE TABLE communications(communication_id NUMBER(19) PRIMARY KEY,communication_type_id NUMBER(5) NOT NULL,sender_entity_id NUMBER(19) NOT NULL,receiver_entity_id NUMBER(19) NOT NULL,start_time TIMESTAMP WITH TIME ZONE NOT NULL,end_time TIMESTAMP WITH TIME ZONE,duration_seconds NUMBER(12),status VARCHAR2(50),content CLOB,source_reference VARCHAR2(500),attributes CLOB DEFAULT '{}' NOT NULL,CONSTRAINT fk_comm_type FOREIGN KEY(communication_type_id) REFERENCES communication_types(communication_type_id),CONSTRAINT fk_comm_sender FOREIGN KEY(sender_entity_id) REFERENCES entities(entity_id),CONSTRAINT fk_comm_receiver FOREIGN KEY(receiver_entity_id) REFERENCES entities(entity_id),CONSTRAINT ck_comm_dur CHECK(duration_seconds IS NULL OR duration_seconds>=0),CONSTRAINT ck_comm_time CHECK(end_time IS NULL OR end_time>=start_time),CONSTRAINT ck_comm_self CHECK(sender_entity_id<>receiver_entity_id));
CREATE TABLE vehicles(vehicle_id NUMBER(19) PRIMARY KEY,external_reference VARCHAR2(100) UNIQUE,vehicle_type VARCHAR2(100),make_model VARCHAR2(200),registration_reference VARCHAR2(100) UNIQUE,attributes CLOB DEFAULT '{}' NOT NULL);
CREATE TABLE entity_vehicles(entity_vehicle_id NUMBER(19) PRIMARY KEY,entity_id NUMBER(19) NOT NULL,vehicle_id NUMBER(19) NOT NULL,relationship_type VARCHAR2(100),valid_from TIMESTAMP WITH TIME ZONE,valid_to TIMESTAMP WITH TIME ZONE,CONSTRAINT fk_ev_entity FOREIGN KEY(entity_id) REFERENCES entities(entity_id) ON DELETE CASCADE,CONSTRAINT fk_ev_vehicle FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id) ON DELETE CASCADE,CONSTRAINT uq_ev UNIQUE(entity_id,vehicle_id,relationship_type));
CREATE TABLE vehicle_sightings(sighting_id NUMBER(19) PRIMARY KEY,vehicle_id NUMBER(19) NOT NULL,location_id NUMBER(19),observed_at TIMESTAMP WITH TIME ZONE NOT NULL,confidence_score NUMBER(5,4),source_reference VARCHAR2(500),attributes CLOB DEFAULT '{}' NOT NULL,CONSTRAINT fk_vs_vehicle FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id) ON DELETE CASCADE,CONSTRAINT fk_vs_location FOREIGN KEY(location_id) REFERENCES locations(location_id),CONSTRAINT ck_vs_conf CHECK(confidence_score IS NULL OR confidence_score BETWEEN 0 AND 1));
CREATE TABLE transactions(transaction_id NUMBER(19) PRIMARY KEY,sender_entity_id NUMBER(19) NOT NULL,receiver_entity_id NUMBER(19) NOT NULL,amount NUMBER(18,2) NOT NULL,currency CHAR(3) NOT NULL,transaction_type VARCHAR2(100) NOT NULL,account_reference VARCHAR2(200),transaction_time TIMESTAMP WITH TIME ZONE NOT NULL,status VARCHAR2(50),source_reference VARCHAR2(500),attributes CLOB DEFAULT '{}' NOT NULL,CONSTRAINT fk_tx_sender FOREIGN KEY(sender_entity_id) REFERENCES entities(entity_id),CONSTRAINT fk_tx_receiver FOREIGN KEY(receiver_entity_id) REFERENCES entities(entity_id),CONSTRAINT ck_tx_amount CHECK(amount>=0),CONSTRAINT ck_tx_self CHECK(sender_entity_id<>receiver_entity_id));
CREATE TABLE evidence_types(evidence_type_id NUMBER(5) PRIMARY KEY,type_name VARCHAR2(50) NOT NULL UNIQUE,base_weight NUMBER(5,4) NOT NULL,CONSTRAINT ck_et_weight CHECK(base_weight BETWEEN 0 AND 1));
CREATE TABLE evidence(evidence_id NUMBER(19) PRIMARY KEY,evidence_type_id NUMBER(5) NOT NULL,collected_at TIMESTAMP WITH TIME ZONE,source_reference VARCHAR2(500),base_confidence NUMBER(5,4) NOT NULL,attributes CLOB DEFAULT '{}' NOT NULL,description CLOB,CONSTRAINT fk_evidence_type FOREIGN KEY(evidence_type_id) REFERENCES evidence_types(evidence_type_id),CONSTRAINT ck_evidence_conf CHECK(base_confidence BETWEEN 0 AND 1));
CREATE TABLE evidence_entities(evidence_entity_id NUMBER(19) PRIMARY KEY,evidence_id NUMBER(19) NOT NULL,entity_id NUMBER(19) NOT NULL,association_confidence NUMBER(5,4) DEFAULT 1 NOT NULL,relation_role VARCHAR2(100),CONSTRAINT fk_eel_evidence FOREIGN KEY(evidence_id) REFERENCES evidence(evidence_id) ON DELETE CASCADE,CONSTRAINT fk_eel_entity FOREIGN KEY(entity_id) REFERENCES entities(entity_id) ON DELETE CASCADE,CONSTRAINT ck_eel_conf CHECK(association_confidence BETWEEN 0 AND 1),CONSTRAINT uq_eel UNIQUE(evidence_id,entity_id,relation_role));
CREATE TABLE evidence_events(evidence_event_id NUMBER(19) PRIMARY KEY,evidence_id NUMBER(19) NOT NULL,event_id NUMBER(19) NOT NULL,CONSTRAINT fk_eex_evidence FOREIGN KEY(evidence_id) REFERENCES evidence(evidence_id) ON DELETE CASCADE,CONSTRAINT fk_eex_event FOREIGN KEY(event_id) REFERENCES events(event_id) ON DELETE CASCADE,CONSTRAINT uq_eex UNIQUE(evidence_id,event_id));
CREATE TABLE investigation_cases(case_id NUMBER(19) PRIMARY KEY,case_reference VARCHAR2(100) NOT NULL UNIQUE,title VARCHAR2(300) NOT NULL,opened_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,incident_time TIMESTAMP WITH TIME ZONE,incident_location_id NUMBER(19),status VARCHAR2(30) DEFAULT 'OPEN' NOT NULL,metadata CLOB DEFAULT '{}' NOT NULL,CONSTRAINT fk_case_loc FOREIGN KEY(incident_location_id) REFERENCES locations(location_id));
CREATE TABLE investigation_queries(query_id NUMBER(5) PRIMARY KEY,query_code VARCHAR2(10) NOT NULL UNIQUE,question_text CLOB NOT NULL,module_name VARCHAR2(100) NOT NULL);
CREATE TABLE sql_modules(module_id NUMBER(5) PRIMARY KEY,module_name VARCHAR2(100) NOT NULL UNIQUE,version VARCHAR2(30) DEFAULT '1.0' NOT NULL,description CLOB NOT NULL);
CREATE TABLE query_modules(query_module_id NUMBER(19) PRIMARY KEY,query_id NUMBER(5) NOT NULL,module_id NUMBER(5) NOT NULL,CONSTRAINT fk_qm_q FOREIGN KEY(query_id) REFERENCES investigation_queries(query_id) ON DELETE CASCADE,CONSTRAINT fk_qm_m FOREIGN KEY(module_id) REFERENCES sql_modules(module_id) ON DELETE CASCADE,CONSTRAINT uq_qm UNIQUE(query_id,module_id));
CREATE TABLE audit_log(audit_id NUMBER(19) PRIMARY KEY,table_name VARCHAR2(128) NOT NULL,operation VARCHAR2(20) NOT NULL,row_pk VARCHAR2(200),changed_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,changed_by VARCHAR2(128) DEFAULT USER NOT NULL,old_data CLOB,new_data CLOB);
